<?php
$q=trim((string)($_GET['q']??''));$like="%$q%";
$s=$db->prepare("SELECT *,DATEDIFF(vencimiento,CURDATE()) dias,fecha_cambio<=CURDATE() AS avisar_cambio FROM productos WHERE producto LIKE ? OR codigo LIKE ? OR categoria LIKE ? OR lote LIKE ? ORDER BY producto,vencimiento");
$s->bind_param('ssss',$like,$like,$like,$like);$s->execute();$rows=$s->get_result();
?>
<section class="panel"><h2>Nuevo producto</h2><form method="post" class="grid-form product-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="product_save"><label class="wide">Producto<input name="producto" required></label><label>Categoría<input name="categoria"></label><label>Proveedor<input name="proveedor"></label><label>Cantidad<input type="number" name="cantidad" min="0" value="0" required></label><label>Vencimiento<input type="date" name="vencimiento" required></label><label class="exchange-check"><input type="checkbox" name="tiene_cambio" value="1"> Tiene cambio con proveedor</label><label class="exchange-date">Fecha para pedir el cambio<input type="date" name="fecha_cambio"></label><button>Guardar producto</button></form></section>
<section class="panel"><div class="panel-head"><h2>Inventario y vencimientos</h2><form class="search"><input type="hidden" name="page" value="productos"><input name="q" value="<?=e($q)?>" placeholder="Buscar producto o categoría"><button>Buscar</button></form></div><div class="table"><table><tr><th>Producto</th><th>Cantidad</th><th>Vencimiento</th><th>Cambio</th><th>Estado</th><th>Acciones</th></tr><?php if(!$rows->num_rows):?><tr><td colspan="6" class="empty">No hay productos registrados</td></tr><?php endif?><?php while($r=$rows->fetch_assoc()):$d=(int)$r['dias'];?><tr class="<?=($r['tiene_cambio']&&$r['avisar_cambio']&&$d>=0)?'exchange-alert':''?>"><td><strong><?=e($r['producto'])?></strong><small><?=e(implode(' · ',array_filter([(string)$r['codigo'],(string)$r['categoria'],(string)$r['lote']!==''?'Lote '.$r['lote']:''])))?></small></td><td><?=e($r['cantidad'])?></td><td><?=e(date('d/m/Y',strtotime($r['vencimiento'])))?></td><td><?php if($r['tiene_cambio']):?><span class="exchange-badge"><?=$r['fecha_cambio']?'Pedir cambio el '.e(date('d/m/Y',strtotime($r['fecha_cambio']))):'Sin fecha de aviso'?></span><?php if($r['avisar_cambio']&&$d>=0):?><strong class="exchange-now">¡Solicitar cambio!</strong><?php endif?><?php else:?>No<?php endif?></td><td><b class="badge <?=$d<0?'bad':($d<=DIAS_PROXIMO?'warn':'good')?>"><?=$d<0?'Vencido':($d<=DIAS_PROXIMO?'Próximo':'Vigente')?></b></td><td><details class="add-expiry"><summary>Editar</summary><form method="post" data-title="Editar producto"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="product_update"><input type="hidden" name="id" value="<?=e($r['id'])?>"><label>Producto<input name="producto" value="<?=e($r['producto'])?>" required></label><label>Categoría<input name="categoria" value="<?=e($r['categoria'])?>"></label><label>Proveedor<input name="proveedor" value="<?=e($r['proveedor'])?>"></label><label>Cantidad<input type="number" name="cantidad" min="0" value="<?=e($r['cantidad'])?>" required></label><label>Vencimiento<input type="date" name="vencimiento" value="<?=e($r['vencimiento'])?>" required></label><label class="exchange-check"><input type="checkbox" name="tiene_cambio" value="1"<?=$r['tiene_cambio']?' checked':''?>> Tiene cambio con proveedor</label><label class="exchange-date">Fecha para pedir el cambio<input type="date" name="fecha_cambio" value="<?=e($r['fecha_cambio'])?>"></label><button>Guardar cambios</button></form></details> <details class="add-expiry"><summary>+ Vencimiento</summary><form method="post" data-title="Agregar otro vencimiento"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="expiration_add"><input type="hidden" name="id" value="<?=e($r['id'])?>"><label>Cantidad<input type="number" name="cantidad" min="0" value="0" required></label><label>Nueva fecha<input type="date" name="vencimiento" required></label><?php if($r['tiene_cambio']):?><label>Fecha para pedir el cambio<input type="date" name="fecha_cambio" required></label><?php endif?><button>Agregar</button></form></details><?php if(admin()):?><form method="post" class="inline-delete" onsubmit="return confirm('¿Eliminar este vencimiento?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="product_delete"><input type="hidden" name="id" value="<?=e($r['id'])?>"><button class="delete">Eliminar</button></form><?php endif?></td></tr><?php endwhile?></table></div></section>
